# The known-correct artifact. Do not modify this file.


def discount(price, tier, coupon):
    if tier == "gold" and price >= 100:
        d = 0.20
    elif tier == "gold":
        d = 0.10
    elif tier == "silver" and price >= 200:
        d = 0.15
    elif tier == "silver":
        d = 0.05
    else:
        d = 0.0
    if coupon:
        d += 0.05
    d = min(d, 0.25)
    return round(price * (1 - d), 2)

