"""The checker. This is the whole gate: if accepts() is True, the artifact ships."""


def accepts(mod):
    try:
        assert mod.discount(150, "gold", False) == 120.0
        assert mod.discount(100, "silver", False) == 95.0
        assert mod.discount(50, "bronze", False) == 50.0
    except Exception:
        return False
    return True

