import math

import answer


def test_wilson_known_value():
    low, high = answer.wilson_interval(40, 100)
    assert abs(low - 0.3093) < 0.002
    assert abs(high - 0.4990) < 0.002


def test_wilson_is_bounded_and_ordered():
    for s, n in [(0, 10), (10, 10), (1, 3), (7, 9)]:
        low, high = answer.wilson_interval(s, n)
        assert 0.0 <= low <= high <= 1.0


def test_wilson_empty():
    assert answer.wilson_interval(0, 0) == (0.0, 1.0)


def test_wilson_narrows_with_n():
    a = answer.wilson_interval(50, 100)
    b = answer.wilson_interval(500, 1000)
    assert (b[1] - b[0]) < (a[1] - a[0])


def test_zero_hit_bound_matches_closed_form():
    assert abs(answer.zero_hit_upper_bound(96, 0.01) - 0.04683) < 1e-4
    assert abs(answer.zero_hit_upper_bound(80, 0.02) - 0.04768) < 1e-4


def test_zero_hit_bound_decreases_in_n():
    vals = [answer.zero_hit_upper_bound(n, 0.01) for n in (10, 50, 96, 200)]
    assert vals == sorted(vals, reverse=True)


def test_zero_hit_edge():
    assert answer.zero_hit_upper_bound(0, 0.01) == 1.0
